CREATE TABLE instances (id TEXT PRIMARY KEY, machine_id TEXT, session_id TEXT, harness TEXT, account_id TEXT, parent_instance_id TEXT, cwd TEXT, title TEXT, model TEXT, effort TEXT, kind TEXT);
CREATE TABLE limit_events (id TEXT PRIMARY KEY, instance_id TEXT, at INTEGER, move TEXT);
CREATE TABLE turn_usage (instance_id TEXT, result_id TEXT, model TEXT, account_id TEXT, input_tokens INTEGER, cache_read_tokens INTEGER, cache_write_tokens INTEGER, cache_write_1h_tokens INTEGER, output_tokens INTEGER, cost_usd REAL, keep_alive INTEGER, at INTEGER);
CREATE TABLE usage_limit_history (id INTEGER PRIMARY KEY AUTOINCREMENT, account_id TEXT, kind TEXT, scope_label TEXT, percent INTEGER, severity TEXT, resets_at TEXT, fetched_at INTEGER);
CREATE TABLE instance_aliases (id TEXT PRIMARY KEY, instance_id TEXT NOT NULL, folded INTEGER NOT NULL DEFAULT 0);
CREATE TABLE instance_conversations (instance_id TEXT NOT NULL, ord INTEGER NOT NULL, session_id TEXT NOT NULL, harness TEXT NOT NULL, model TEXT, account_id TEXT, ended_at INTEGER NOT NULL, next_event_id TEXT, PRIMARY KEY (instance_id, ord));
